Library IEEE;use IEEE.Std_Logic_unsigned.all;use IEEE.Std_Logic_1164.all;entity Counter is	generic (R2_size: integer := 4);	port (R2: buffer Std_Logic_vector  (R2_size -1 downto 0);	Load_regs, Incr_R2: in Std_Logic; clock, reset_b: in Std_Logic);end Counter;architecture Behavioral of Counter isbegin		process (clock, reset_b) begin	if reset_b = '0' then for k in 0 to R2_size -1 loop R2(k) <= '0'; 	end loop;	elsif clock'event and clock = '1' then 		if Load_regs = '1' then for k in 0 to R2_size -1 loop 			R2(k) <= '1'; 		end loop;		elsif Incr_R2 = '1' then R2 <= R2 + 1;		end if;	end if;	end if;	end process;end Behavioral;